def _mount_has_pquota(opts):
    if not opts:
        return False
    return "pquota" in opts or "prjquota" in opts

def _docker_dir_has_data():
    """Whether /var/lib/docker exists and holds data that must be moved aside
    before mounting new storage over it. Shared by the --docker-partition and
    auto-partition/loopback flows so identical host state yields identical
    stop/rename/rsync behavior regardless of install mode."""
    return bool(os.path.exists(DOCKER_DIR_NOS) and os.listdir(DOCKER_DIR_NOS))

def setup_storage_from_partition(device):
    """Prepare an explicit user-supplied partition as /var/lib/docker storage.

    Validates the device, formats it XFS if empty, refuses non-XFS, refuses to
    reformat the vast_client_data partition, rewrites /etc/fstab with a UUID
    entry, and mounts. Raises InstallFailed on any unsafe condition.
    """
    if not os.path.exists(device):
        raise InstallFailed(f"--docker-partition: {device} does not exist.")
    try:
        st_mode = os.stat(device).st_mode
    except OSError as e:
        raise InstallFailed(f"--docker-partition: cannot stat {device}: {e}")
    if not stat.S_ISBLK(st_mode):
        raise InstallFailed(f"--docker-partition: {device} is not a block device.")

    real_device = os.path.realpath(device)

    mounts_by_source = get_mounts(dict_field=0)
    mounts_by_dest = {os.path.abspath(k): v for k, v in get_mounts(dict_field=1).items()}

    existing_docker_mount = mounts_by_dest.get(os.path.abspath(DOCKER_DIR_NOS))
    if existing_docker_mount is not None:
        existing_source = os.path.realpath(existing_docker_mount[0])
        if existing_source != real_device:
            raise InstallFailed(
                f"{DOCKER_DIR_NOS} is already mounted from {existing_docker_mount[0]} but "
                f"--docker-partition requested {device}. Unmount the current Docker storage "
                f"first, or re-run without --docker-partition to keep the existing mount."
            )
        if existing_docker_mount[2] != "xfs" or not _mount_has_pquota(existing_docker_mount[3]):
            raise InstallFailed(
                f"{DOCKER_DIR_NOS} is mounted from {device} but with the wrong filesystem or "
                f"options (type={existing_docker_mount[2]}, opts={existing_docker_mount[3]}). "
                f"Expected xfs with prjquota."
            )
        log(f"=> Reusing existing {DOCKER_DIR_NOS} mount from {device}", level=2)
        return

    if real_device in mounts_by_source:

        process_call(["systemctl", "start", "docker"], stdout=logfile, stderr=logfile)

